insert into public.products (id, kind, name, details, images, value_pkr, breed, age, weight, type, owner, warranty, life_span, created_at) values ('eq_chaff_cutter', 'equipment', 'Heavy-Duty Chaff Cutter', 'An electric chaff cutter that turns green fodder into an even, digestible cut. Less waste at the trough and noticeably better feed conversion across the herd.', '[{"url":"https://images.unsplash.com/photo-1625246333195-78d9c38ad449?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1},{"url":"https://images.unsplash.com/photo-1574943320219-553eb213f72d?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1}]'::jsonb, 165000, null, null, null, null, '{"ownedByFarm":true}'::jsonb, '1 year', '12 years', '2026-08-14T13:42:05.581061+00:00') on conflict (id) do nothing;

insert into public.products (id, kind, name, details, images, value_pkr, breed, age, weight, type, owner, warranty, life_span, created_at) values ('eq_solar_pump', 'equipment', 'Solar Water Pump System', 'A solar-powered pump that keeps the water troughs full through load-shedding and summer peaks, with no diesel cost and almost no running expense.', '[{"url":"https://images.unsplash.com/photo-1509391366360-2e959784a276?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1},{"url":"https://images.unsplash.com/photo-1466611653911-95081537e5b7?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1}]'::jsonb, 420000, null, null, null, null, '{"ownedByFarm":true}'::jsonb, '5 years (panels)', '20 years', '2026-08-14T13:42:05.581061+00:00') on conflict (id) do nothing;

insert into public.products (id, kind, name, details, images, value_pkr, breed, age, weight, type, owner, warranty, life_span, created_at) values ('eq_milk_chiller', 'equipment', '500L Milk Chilling Tank', 'A stainless-steel bulk chiller that brings fresh milk down to 4°C within the safe window — protecting quality, cutting spoilage, and opening better markets.', '[{"url":"https://images.unsplash.com/photo-1563636619-e9143da7973b?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1},{"url":"https://images.unsplash.com/photo-1550583724-b2692b85b150?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1}]'::jsonb, 950000, null, null, null, null, '{"ownedByFarm":true}'::jsonb, '3 years', '15 years', '2026-08-14T13:42:05.581061+00:00') on conflict (id) do nothing;

insert into public.products (id, kind, name, details, images, value_pkr, breed, age, weight, type, owner, warranty, life_span, created_at) values ('eq_milking_machine', 'equipment', 'Twin-Bucket Milking Machine', 'A portable twin-bucket milking unit that lets one caretaker milk two animals at a time — faster, cleaner, and far gentler on the herd than hand milking.', '[{"url":"https://images.unsplash.com/photo-1560493676-04071c5f467b?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1},{"url":"https://images.unsplash.com/photo-1595872018818-97555653a011?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1}]'::jsonb, 285000, null, null, null, null, '{"ownedByFarm":true}'::jsonb, '2 years', '10 years', '2026-08-14T13:42:05.581061+00:00') on conflict (id) do nothing;

insert into public.products (id, kind, name, details, images, value_pkr, breed, age, weight, type, owner, warranty, life_span, created_at) values ('cow_noor', 'livestock', 'Noor', 'A young calf full of energy, just beginning her life on the farm. Curious, playful, and already a favourite with the caretakers.', '[{"url":"https://images.unsplash.com/photo-1502590464431-3b66d77494d7?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1},{"url":"https://images.unsplash.com/photo-1570042225831-d98fa7577f1e?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1},{"url":"https://images.unsplash.com/photo-1500595046743-cd271d694d30?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1}]'::jsonb, 120000, 'Sahiwal', '8 months', '180 kg', 'Calf', '{"cnic":"","email":"","phone":"","lastName":"","firstName":"","ownedByFarm":true}'::jsonb, null, null, '2026-08-14T13:42:05.581061+00:00') on conflict (id) do nothing;

insert into public.products (id, kind, name, details, images, value_pkr, breed, age, weight, type, owner, warranty, life_span, created_at) values ('cow_sultan', 'livestock', 'Sultan', 'A confident, strong bull — a steady presence and the pride of the herd. Well cared for and central to the farm’s growing legacy.', '[{"url":"https://images.unsplash.com/photo-1589248529232-69c286cf2cb4?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1},{"url":"https://images.unsplash.com/photo-1545407263-7ff5aa2ad921?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1},{"url":"https://images.unsplash.com/photo-1546445317-29f4545e9d53?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1}]'::jsonb, 300000, 'Nili-Ravi cross', '3 years', '520 kg', 'Bull', '{"cnic":"35202-7654321-1","email":"akbar@example.com","phone":"+92 321 7654321","lastName":"Akbar","firstName":"Ghulam","ownedByFarm":false}'::jsonb, null, null, '2026-08-14T13:42:05.581061+00:00') on conflict (id) do nothing;

insert into public.products (id, kind, name, details, images, value_pkr, breed, age, weight, type, owner, warranty, life_span, created_at) values ('cow_champa', 'livestock', 'Champa', 'A gentle young heifer settling well into farm life under our team’s care. Calm around people and steadily growing stronger each week.', '[{"url":"https://images.unsplash.com/photo-1596733430284-f7437764b1a9?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1},{"url":"https://images.unsplash.com/photo-1564085352725-08da0272627d?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1},{"url":"https://images.unsplash.com/photo-1561043394-9f7d16d9ae37?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1},{"url":"https://images.unsplash.com/photo-1580570598977-4b2412d01bbc?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1}]'::jsonb, 180000, 'Cholistani', '1.5 years', '320 kg', 'Heifer', '{"cnic":"35202-1234567-8","email":"","phone":"+92 300 1234567","lastName":"Bibi","firstName":"Rukhsana","ownedByFarm":false}'::jsonb, null, null, '2026-08-14T13:42:05.581061+00:00') on conflict (id) do nothing;

insert into public.products (id, kind, name, details, images, value_pkr, breed, age, weight, type, owner, warranty, life_span, created_at) values ('cow_sabz', 'livestock', 'Sabz', 'A calm, steady milking cow — one of the herd’s most reliable mothers. Her fresh milk helps sustain the families the farm supports.', '[{"url":"https://images.unsplash.com/photo-1527153857715-3908f2bae5e8?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1},{"url":"https://images.unsplash.com/photo-1595664652035-0956d50e0311?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1},{"url":"https://images.unsplash.com/photo-1595365691689-6b7b4e1970cf?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1}]'::jsonb, 260000, 'Sahiwal', '4 years', '420 kg', 'Cow', '{"cnic":"","email":"","phone":"","lastName":"","firstName":"","ownedByFarm":true}'::jsonb, null, null, '2026-08-14T13:42:05.581061+00:00') on conflict (id) do nothing;

insert into public.products (id, kind, name, details, images, value_pkr, breed, age, weight, type, owner, warranty, life_span, created_at) values ('cow_bijli', 'livestock', 'Bijli', 'A relaxed, well-fed cow who loves fresh fodder at the feed trough. Healthy, content, and thriving in the farm’s managed care.', '[{"url":"https://images.unsplash.com/photo-1618080206739-14e8ac105472?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1},{"url":"https://images.unsplash.com/photo-1593768697824-f31b967e6c55?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1},{"url":"https://images.unsplash.com/photo-1620811004671-40b81b6f6978?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1},{"url":"https://images.unsplash.com/photo-1604860428762-f55cea62b7a0?auto=format&fit=crop&w=1000&h=1250&q=80","posX":50,"posY":50,"zoom":1}]'::jsonb, 240000, 'Red Sindhi', '5 years', '450 kg', 'Cow', '{"cnic":"","email":"","phone":"","lastName":"","firstName":"","ownedByFarm":true}'::jsonb, null, null, '2026-08-14T13:42:05.581061+00:00') on conflict (id) do nothing;

update public.app_settings set multi_select = true, gather_recipient_info = true, collect_owner_info = true, reservation_days = 7, terms = 'By proceeding with a sponsorship with IGA Sial Farm, you acknowledge and agree to the following:

1. Your sponsorship supports the Sponsor-a-Livestock and Equipment program and the wider work of IGA Sial Farm, a not-for-profit, community-first initiative in Punjab, Pakistan.

2. Sponsorships are voluntary contributions. Once an animal or item of equipment is sponsored, it is non-refundable.

3. The sponsorship value shown for each animal or item of equipment is indicative. Foreign-currency amounts (USD, AUD, SAR) are converted from PKR at periodically updated exchange rates and may vary slightly at the time of transfer.

4. Where partial sponsorship is offered, your contribution is held against the item until its full value is reached. If the remaining balance is not completed, or a contribution is cancelled or released, the item is returned to the available pool.

5. You will receive a personalised sponsorship certificate and periodic welfare updates for the animal or equipment you support, subject to availability.

6. IGA Sial Farm reinvests 100% of program profits into education, jobs, animal care, and community development."

7. The details you provide (name, email, phone) are used solely to process your sponsorship, issue your certificate, and keep you updated. They are never sold or shared for marketing.

8. Please transfer your sponsorship to one of the bank accounts listed below and retain your transfer receipt. Our team will confirm receipt and complete the sponsorship on your behalf.', banks = '[{"id":"bank_hbl","iban":"PK36HABB0001790012345670","swift":"HABBPKKA","branch":"Waryam Wala, Punjab","bankName":"Habib Bank Limited (HBL)","currency":"PKR","accountTitle":"IGA Sial Farm","accountNumber":"0001-79001234567"},{"id":"bank_meezan","iban":"PK24MEZN0102011012345600","swift":"MEZNPKKA","branch":"Lahore Main","bankName":"Meezan Bank","currency":"PKR","accountTitle":"IGA Sial Farm","accountNumber":"0102-0110123456"},{"id":"bank_wise","iban":"","swift":"TRWIUS35XXX","branch":"International wire (USD)","bankName":"Wise (USD)","currency":"USD","accountTitle":"IGA Sial Farm","accountNumber":"8310 1234 5678"}]'::jsonb, fx_rates = '{"AUD":183,"SAR":74.3,"USD":278.5}'::jsonb, partial_enabled = false, partial_livestock_enabled = false, partial_livestock_min = 100000, partial_equipment_enabled = false, partial_equipment_min = 200000 where id = 1;

